		assertEquals(3.0d,
				bundleType.getMethod("exactWeight", int.class, int.class, int.class).invoke(bundle, 1, 0, 1));
		assertTrue((long) bundleType.getMethod("retainedBytes").invoke(bundle) > 0L);
