	@Test
	void referencesAreArenaScopedAndSummariesAreImmutable() {
		try (FrontierStateArena first = new FrontierStateArena(64 * 1024L);
				FrontierStateArena second = new FrontierStateArena(64 * 1024L)) {
			FrontierLayout layout = FrontierLayout.of("x", "y");
			EvidenceStateSummary summary = EvidenceStateSummary.exact(3.0d);
			EvidenceStateRef reference = first.append(layout, summary);

			assertTrue(first.owns(reference));
			assertEquals(summary, first.summary(reference));
			assertEquals(summary, reference.summary());
			assertEquals(layout, first.layout(reference));
			assertThrows(IllegalArgumentException.class, () -> second.summary(reference));
			assertEquals(1, first.size());
			assertTrue(first.allocatedBytes() <= first.memoryBudgetBytes());
		}
	}

	@Test
	void zeroAndInsufficientArenaBudgetsAreRejected() {
		assertThrows(IllegalArgumentException.class, () -> new FrontierStateArena(0L));
		assertThrows(IllegalArgumentException.class, () -> new FrontierStateArena(1L));
	}

	@Test
	void rejectedReservationReportsTypedAtomicResourceLimit() {
		try (FrontierStateArena arena = new FrontierStateArena(64 * 1024L)) {
			long reservedBefore = arena.allocatedBytes();

			FrontierMemoryLimitException failure = assertThrows(FrontierMemoryLimitException.class,
					() -> arena.reserveTemporary(Long.MAX_VALUE, FrontierMemoryPurpose.ARRAY_GROWTH));

			assertEquals(Long.MAX_VALUE, failure.requestedBytes());
			assertEquals(reservedBefore, failure.reservedBytes());
			assertEquals(arena.memoryBudgetBytes(), failure.limitBytes());
			assertEquals(FrontierMemoryPurpose.ARRAY_GROWTH, failure.purpose());
			assertEquals(reservedBefore, arena.allocatedBytes(), "a rejected reservation must publish no arena state");
			try (FrontierMemoryReservation ignored = arena.reserveTemporary(1L,
					FrontierMemoryPurpose.ARRAY_GROWTH)) {
				assertTrue(arena.allocatedBytes() > reservedBefore);
			}
			assertEquals(reservedBefore, arena.allocatedBytes());
		}
	}

	@Test
	void closedArenaRejectsStateAccess() {
		FrontierStateArena arena = new FrontierStateArena(64 * 1024L);
		EvidenceStateRef reference = arena.append(FrontierLayout.empty(), EvidenceStateSummary.exact(1.0d));
		arena.close();

		assertThrows(IllegalStateException.class, () -> arena.summary(reference));
		assertThrows(IllegalStateException.class, arena::size);
		assertEquals(0L, arena.allocatedBytes());
	}

	private static EvidenceStateSummary summary(EvidenceGuarantee guarantee, EvidenceZeroStatus zeroStatus,
			double pointRows, double upperRows) {
		return new EvidenceStateSummary(
				pointRows,
				0.0d,
				upperRows,
				0.95d,
				EvidenceIntervalKind.POINTWISE,
				1.0d,
				2.0d,
				3.0d,
				4.0d,
				pointRows == 0.0d ? 0.0d : 0.5d,
				upperRows,
				guarantee,
				zeroStatus,
				"");
	}

	private static EvidenceStateRef exactLeaf(FrontierStateArena arena, FrontierStateKey key, long termId,
			int recipeId) {
		try (FrontierPayloadWriter writer = arena.newPayloadWriter(key, new int[] { 1 }, new int[] { 0 })) {
			writer.putExact(0, 0, 1.0d, new long[] { termId }, 0);
			return arena.internPayload(key, EvidenceStateSummary.exact(1.0d),
					FrontierStateOperation.EXACT_LEAF, null, null, recipeId, writer);
		}
	}

	private static EvidenceStateRef exactUnaryPayload(FrontierStateArena arena, FrontierStateKey key,
			EvidenceStateRef input, long termId, int recipeId) {
		try (FrontierPayloadWriter writer = arena.newPayloadWriter(key, new int[] { 1 }, new int[] { 0 })) {
			writer.putExact(0, 0, 1.0d, new long[] { termId }, 0);
			return arena.internPayload(key, EvidenceStateSummary.exact(1.0d),
					FrontierStateOperation.PROJECT, input, null, recipeId, writer);
		}
	}

	private static long arrayBytes(int length, int elementBytes) {
		long bytes = 16L + (long) length * elementBytes;
		return bytes + 7L & ~7L;
	}

	private static FrontierStateKey key(
			long[] factors,
			FrontierLayout frontier,
			long[] masks,
			long semanticScope,
			long correlationScope,
			long continuationObjective,
			long snapshotStoreId,
			long snapshotEpoch,
			int laneRole,
			int seedVersion) {
		return FrontierStateKey.of(
				factors,
				frontier,
				masks,
				semanticScope,
				correlationScope,
				continuationObjective,
				snapshotStoreId,
				snapshotEpoch,
				laneRole,
				seedVersion);
	}
